package org.nonfood.oilplants.service;
import org.junit.jupiter.api.Test;import org.nonfood.oilplants.dao.PlantDao;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class PlantServiceValidationTest {
 @Test void rejectsInvertedAndOutOfRangeQueryBounds(){PlantService s=new PlantService(mock(PlantDao.class));assertThrows(IllegalArgumentException.class,()->s.criteria(Map.of("oilMin",new String[]{"70"},"oilMax",new String[]{"20"})));assertThrows(IllegalArgumentException.class,()->s.criteria(Map.of("componentMin",new String[]{"-1"})));assertThrows(IllegalArgumentException.class,()->s.criteria(Map.of("oilMax",new String[]{"101"})));assertThrows(IllegalArgumentException.class,()->s.criteria(Map.of("oilMin",new String[]{"10.1234"})));}
 @Test void acceptsNumericBoundsAndWhitelistsSort(){PlantService s=new PlantService(mock(PlantDao.class));var c=s.criteria(Map.of("oilMin",new String[]{"12.5"},"oilMax",new String[]{"90"},"sort",new String[]{"bad"},"direction",new String[]{"bad"},"page",new String[]{"0"}));assertEquals(1,c.getPage());assertEquals("name",c.getSort());assertEquals("asc",c.getDirection());assertEquals("12.5",c.getOilMin().toPlainString());}
 @Test void keepsOilSampleAndComponentStatusesSeparate()throws Exception{PlantDao dao=mock(PlantDao.class);PlantService service=new PlantService(dao);service.updateSample(7,9,"seed","15.25","p. 3",null,"oleic=40.5","UNVERIFIED","VERIFIED","NEEDS_REVIEW");org.mockito.ArgumentCaptor<org.nonfood.oilplants.model.OilSample> sample=org.mockito.ArgumentCaptor.forClass(org.nonfood.oilplants.model.OilSample.class);verify(dao).updateSample(org.mockito.ArgumentMatchers.eq(7L),sample.capture(),org.mockito.ArgumentMatchers.argThat(acids->acids.size()==1&&"NEEDS_REVIEW".equals(acids.get(0).getVerificationStatus())));assertEquals("UNVERIFIED",sample.getValue().getVerificationStatus());assertEquals("VERIFIED",sample.getValue().getOilContentStatus());assertThrows(IllegalArgumentException.class,()->service.updateSample(7,9,"seed",null,"p. 3",null,"oleic=40.5","VERIFIED","VERIFIED","VERIFIED"));assertThrows(IllegalArgumentException.class,()->service.updateSample(7,9,"seed","15.25","p. 3",null,"oleic=40.5","VERIFIED","MISSING_OR_UNREADABLE","VERIFIED"));}
}
